INSERT INTO body_part_texts (body_part_id, lang, name, short_name, line, feels) VALUES
  (1, 'en', 'Head and face', 'Head', 'Forty-odd muscles, and the part of the body people watch first.', 'Anger, fear and joy all register strongly in the head in body-mapping studies: heat, pressure, a rush.'),
  (1, 'ckb', 'سەر و دەموچاو', 'سەر', 'نزیکەی چل ماسولکە، و ئەو بەشەی جەستە کە خەڵک یەکەمجار سەیری دەکەن.', 'لە توێژینەوەکانی نەخشەی جەستەدا، تووڕەیی و ترس و خۆشی هەموویان بە بەهێزی لە سەردا هەستیان پێدەکرێت: گەرمی، فشار، هەڵچوون.'),
  (2, 'en', 'Brows', 'Brows', 'The most expressive few centimetres on the body.', 'The frowning muscle tenses slightly in bad moods even when nothing shows; sensors on the skin pick it up.'),
  (2, 'ckb', 'برۆکان', 'برۆ', 'گوزارشتکارترین چەند سانتیمەترەکەی جەستە.', 'ماسولکەی ڕووگرژی لە کاتی بێکەیفیدا کەمێک گرژ دەبێت تەنانەت ئەگەر هیچ دیار نەبێت؛ هەستەوەرەکانی سەر پێست دەیگرن.'),
  (3, 'en', 'Eyes', 'Eyes', 'Where most readings start, and many go wrong.', 'Fear widens the eyes and lets in more light; disgust narrows them and shuts it out.'),
  (3, 'ckb', 'چاوەکان', 'چاو', 'زۆربەی خوێندنەوەکان لێرەوە دەست پێدەکەن، و زۆریشیان لێرەوە هەڵە دەچن.', 'ترس چاوەکان فراوان دەکات و ڕووناکیی زیاتر دەهێڵێتە ژوورەوە؛ قێزلێبوونەوە تەسکیان دەکاتەوە و ڕووناکی دادەخات.'),
  (4, 'en', 'Mouth', 'Mouth', 'The easiest part to control, so the first one people manage.', 'Stress cuts saliva: a dry mouth before a talk is the body getting ready to act, not to eat.'),
  (4, 'ckb', 'دەم', 'دەم', 'ئاسانترین بەشە بۆ کۆنترۆڵکردن، بۆیە یەکەم بەشە کە خەڵک دەستکاری دەکەن.', 'فشار تف کەم دەکاتەوە: دەمی وشک پێش وتارێک، جەستەیە کە خۆی بۆ کار ئامادە دەکات، نەک بۆ خواردن.'),
  (5, 'en', 'Skin and colour', 'Skin', 'Signals you cannot fake and cannot hide.', 'Darwin called blushing "the most peculiar and the most human of all expressions".'),
  (5, 'ckb', 'پێست و ڕەنگ', 'پێست', 'ئاماژەگەلێک کە نە دەتوانیت ساختەیان بکەیت و نە بیانشاریتەوە.', 'داروین سووربوونەوەی بە "سەیرترین و مرۆڤانەترینی هەموو دەربڕینەکان" ناوبرد.'),
  (6, 'en', 'Throat and neck', 'Throat', 'A vulnerable place, and the body knows it.', 'The "lump in the throat" in sadness and anxiety is real muscle tension around the throat.'),
  (6, 'ckb', 'گەروو و مل', 'گەروو', 'شوێنێکی ناسکە، و جەستە ئەمە دەزانێت.', '"گرێی گەروو" لە خەم و دڵەڕاوکێدا گرژییەکی ڕاستەقینەی ماسولکەکانی دەوری گەرووە.'),
  (7, 'en', 'Shoulders', 'Shoulders', 'They rise with the world and fall with the self.', 'Stress parks itself here: the trapezius muscles tighten and stay tight.'),
  (7, 'ckb', 'شانەکان', 'شان', 'لەگەڵ جیهان بەرز دەبنەوە و لەگەڵ خود دادەکەون.', 'فشار لێرە نیشتەجێ دەبێت: ماسولکەکانی سەرشان گرژ دەبن و بە گرژی دەمێننەوە.'),
  (8, 'en', 'Chest', 'Chest', 'Where most strong feelings are felt first.', 'In body maps, the chest lights up in anger, fear, pride, love and anxiety. A tight chest is the classic sign of anxiety.'),
  (8, 'ckb', 'سنگ', 'سنگ', 'ئەو شوێنەی زۆربەی هەستە بەهێزەکان یەکەمجار تێیدا هەستیان پێدەکرێت.', 'لە نەخشەکانی جەستەدا، سنگ لە تووڕەیی، ترس، شانازی، خۆشەویستی و دڵەڕاوکێدا ڕووناک دەبێتەوە. سنگی تەنگ نیشانەی کلاسیکیی دڵەڕاوکێیە.'),
  (9, 'en', 'Arms', 'Arms', 'The body''s shield, and its loudest flag.', 'Anger floods the arms in body maps: the body getting ready to push.'),
  (9, 'ckb', 'باسکەکان', 'باسک', 'قەڵغانی جەستە، و دەنگبەرزترین ئاڵاکەی.', 'لە نەخشەکانی جەستەدا تووڕەیی باسکەکان پڕ دەکات: جەستە خۆی ئامادە دەکات بۆ پاڵنان.'),
  (10, 'en', 'Hands', 'Hands', 'Busy when the mind is busy.', 'Fear makes hands cold (blood moves to the core) and palms sweaty; skin sweat is how lie detectors measure arousal, not lies.'),
  (10, 'ckb', 'دەستەکان', 'دەست', 'کاتێک مێشک سەرقاڵە، ئەوانیش سەرقاڵن.', 'ترس دەستەکان سارد دەکات (خوێن بەرەو ناوەڕاستی جەستە دەچێت) و ناولەپ ئارەقە دەکات؛ ئارەقەی پێست ئەوەیە کە ئامێری درۆدۆزەرەوە دەیپێوێت: وروژان، نەک درۆ.'),
  (11, 'en', 'Stomach', 'Stomach', 'The gut reacts before the thought arrives.', '"Butterflies" are blood leaving the gut under stress. Disgust and anxiety are felt here most strongly in body maps; nausea is disgust''s oldest job.'),
  (11, 'ckb', 'سک', 'سک', 'ڕیخۆڵە پێش گەیشتنی بیرکردنەوە کاردانەوەی هەیە.', '"پەپوولەکانی ناو سک" خوێنن کە لە کاتی فشاردا ڕیخۆڵە جێدەهێڵن. لە نەخشەکانی جەستەدا قێزلێبوونەوە و دڵەڕاوکێ لێرە بەهێزترین هەستیان پێدەکرێت؛ هێڵنج کۆنترین ئەرکی قێزلێبوونەوەیە.'),
  (12, 'en', 'Legs', 'Legs', 'Furthest from the face, so the least managed.', 'Fear readies the legs to run, or freezes them. Sadness and depression make limbs feel heavy and drained.'),
  (12, 'ckb', 'قاچەکان', 'قاچ', 'دوورترین بەشن لە دەموچاو، بۆیە کەمترین کۆنترۆڵیان لەسەرە.', 'ترس قاچەکان بۆ ڕاکردن ئامادە دەکات، یان دەیانبەستێت. خەم و خەمۆکی وا دەکەن ئەندامەکان قورس و بێهێز هەستیان پێبکرێت.'),
  (13, 'en', 'Feet', 'Feet', 'They often point where we want to go.', 'Feet get cold first when you are afraid: blood moves to where it might be needed.'),
  (13, 'ckb', 'پێیەکان', 'پێ', 'زۆرجار ڕوو لەو شوێنە دەکەن کە دەمانەوێت بچینە ئەوێ.', 'کاتێک دەترسیت پێیەکان یەکەمجار سارد دەبن: خوێن بەرەو ئەو شوێنانە دەچێت کە لەوانەیە پێویستی پێیان بێت.');
