INSERT INTO signal_texts (signal_id, lang, tell, means, context) VALUES
  (1, 'en', 'Head tilted to one side', 'Listening, interest, softening a question.', 'With a frown and narrowed eyes it reads as doubt instead.'),
  (1, 'ckb', 'لارکردنەوەی سەر بۆ لایەک', 'گوێگرتن، سەرنج، نەرمکردنی پرسیارێک.', 'لەگەڵ ڕووگرژی و چاوی تەسک، وەک گومان دەخوێنرێتەوە.'),
  (2, 'en', 'Chin lifted, head back', 'Pride or triumph. People born blind show it after winning too.', 'Held while looking down the nose, it reads as contempt.'),
  (2, 'ckb', 'چەناگە بەرز، سەر بۆ دواوە', 'شانازی یان سەرکەوتن. ئەوانەی بە نابینایی لەدایک بوون، دوای بردنەوە هەمان شت دەکەن.', 'ئەگەر لە هەمان کاتدا بە سەر لووتدا سەیری خوارەوە بکات، وەک بەکەمزانین دەخوێنرێتەوە.'),
  (3, 'en', 'Head bowed', 'Shame, sadness, deference, or simply reading.', 'Before an elder or a boss in many cultures, it is respect.'),
  (3, 'ckb', 'سەرشۆڕی', 'شەرم، خەم، ڕێزگرتن، یان تەنها خوێندنەوە.', 'لە زۆر کولتووردا، لەبەردەم بەتەمەنێک یان بەڕێوەبەرێک، ڕێزگرتنە.'),
  (4, 'en', 'Inner ends lifted and drawn together', 'Worry, grief, pleading. Few people can do it on purpose.', 'Fleeting, while listening to bad news: empathy rather than personal sadness.'),
  (4, 'ckb', 'سەرە ناوەکییەکانی برۆ بەرز و لێک نزیک', 'نیگەرانی، خەفەت، پاڕانەوە. کەم کەس دەتوانێت بە ئەنقەست بیکات.', 'ئەگەر بە خێرایی دەربکەوێت لە کاتی بیستنی هەواڵێکی خراپدا: هاوسۆزییە، نەک خەمی کەسی خۆی.'),
  (5, 'en', 'Pulled down and together', 'Concentration, confusion, bright light, or anger.', 'Alone it is one of the most misread signals. Look at the task in front of them.'),
  (5, 'ckb', 'برۆ بۆ خوارەوە و پێکەوە ڕاکێشراو', 'سەرنجدان، سەرلێشێوان، ڕووناکیی زۆر، یان تووڕەیی.', 'بە تەنها، یەکێکە لەو ئاماژانەی زۆرترین هەڵەخوێندنەوەی بۆ دەکرێت. سەیری ئەو کارە بکە کە لەبەردەمیدایە.'),
  (6, 'en', 'A quick lift on meeting someone', 'The "eyebrow flash": recognition and greeting, seen across many cultures.', 'Held up and still, it becomes surprise or disbelief.'),
  (6, 'ckb', 'بەرزبوونەوەیەکی خێرا کاتی بینینی کەسێک', '"برۆهەڵدان": ناسینەوە و سڵاوکردن، لە زۆر کولتووردا دەبینرێت.', 'ئەگەر بەرز و جێگیر بمێنێتەوە، دەبێتە سەرسوڕمان یان باوەڕنەکردن.'),
  (7, 'en', 'Pupils widening', 'Interest, mental effort, arousal. Nobody controls it.', 'Light changes pupils far more than feelings do; a dark room widens everyone.'),
  (7, 'ckb', 'گەورەبوونی بیلبیلە', 'سەرنج، هەوڵی مێشک، وروژان. کەس کۆنترۆڵی ناکات.', 'ڕووناکی زۆر زیاتر لە هەست بیلبیلە دەگۆڕێت؛ ژوورێکی تاریک بیلبیلەی هەمووان گەورە دەکات.'),
  (8, 'en', 'Crinkled outer corners', 'Often comes with a felt smile.', 'Many people can produce it on purpose, so it is a hint, not proof.'),
  (8, 'ckb', 'چرچبوونی گۆشەی دەرەوەی چاو', 'زۆرجار لەگەڵ زەردەخەنەیەکی ڕاستەقینەدا دێت.', 'زۆر کەس دەتوانن بە ئەنقەست دروستی بکەن، کەواتە ئاماژەیە، نەک بەڵگە.'),
  (9, 'en', 'Looking away while answering', 'Usually thinking: it frees the brain from processing a face.', 'It does not mean lying. Liars, on average, hold eye contact as much as anyone.'),
  (9, 'ckb', 'سەیرکردنی لایەکی تر لە کاتی وەڵامدانەوەدا', 'زۆربەی کات بیرکردنەوەیە: مێشک لە پرۆسێسکردنی دەموچاوێک ڕزگار دەکات.', 'مانای درۆکردن نییە. درۆزنەکان، بە تێکڕا، بە هەمان ئەندازەی هەمووان سەیری چاوت دەکەن.'),
  (10, 'en', 'Eyes up and to the right means a lie', 'Tested directly and found to mean nothing.', 'A famous body-language myth. Included so you can stop believing it.'),
  (10, 'ckb', 'چاو بۆ سەرەوە و لای ڕاست واتە درۆ', 'ڕاستەوخۆ تاقیکراوەتەوە و دەرکەوتووە هیچ مانایەکی نییە.', 'ئەفسانەیەکی بەناوبانگی زمانی جەستەیە. لێرە داندراوە بۆ ئەوەی واز لە باوەڕپێکردنی بهێنیت.'),
  (11, 'en', 'Lips pressed thin', 'Holding something back: words, anger, effort, tears.', 'During hard concentration it means nothing emotional at all.'),
  (11, 'ckb', 'لێوەکان بە توندی پێکەوە نراون', 'ڕاگرتنی شتێک: قسە، تووڕەیی، هەوڵ، فرمێسک.', 'لە کاتی سەرنجدانی قووڵدا هیچ مانایەکی هەستیی نییە.'),
  (12, 'en', 'A smile that arrives and leaves fast', 'Social politeness. It is a greeting, not a lie.', 'Held too long after the moment passes, people start to read it as strained.'),
  (12, 'ckb', 'زەردەخەنەیەک کە خێرا دێت و خێرا دەڕوات', 'ڕێزی کۆمەڵایەتی. سڵاوێکە، نەک درۆ.', 'ئەگەر دوای تێپەڕبوونی ساتەکە زۆر بمێنێتەوە، خەڵک وەک زۆرەملێ دەیخوێننەوە.'),
  (13, 'en', 'Biting or licking the lips', 'Nerves (stress dries the mouth), or concentration.', 'Also just dry air or chapped lips. Check the baseline.'),
  (13, 'ckb', 'گەستن یان لێسینەوەی لێو', 'دڵەڕاوکێ (فشار دەم وشک دەکات)، یان سەرنجدان.', 'هەروەها هەوای وشک یان لێوی قڵیشاو. سەیری باری ئاسایی کەسەکە بکە.'),
  (14, 'en', 'Blushing', 'Embarrassment, being looked at, being caught out.', 'Others usually forgive faster when you blush; it works like an apology.'),
  (14, 'ckb', 'سووربوونەوە', 'شەرمەزاری، لێڕوانین، گیران لەسەر هەڵەیەک.', 'خەڵک زۆرجار خێراتر دەتبوورن کاتێک سوور دەبیتەوە؛ وەک داوای لێبوردن کار دەکات.'),
  (15, 'en', 'Going pale', 'Fear or shock: blood leaves the skin for the muscles.', 'Also cold, illness or low blood sugar.'),
  (15, 'ckb', 'ڕەنگ پەڕین', 'ترس یان شۆک: خوێن پێست جێدەهێڵێت و بەرەو ماسولکەکان دەچێت.', 'هەروەها سەرما، نەخۆشی یان کەمیی شەکری خوێن.'),
  (16, 'en', 'A hand to the neck', 'Self-soothing under stress or uncertainty.', 'Also an itch, a necklace, a habit. One touch means little; a pattern means more.'),
  (16, 'ckb', 'دەست بۆ مل بردن', 'ئارامکردنەوەی خۆ لە کاتی فشار یان دڵنیانەبووندا.', 'هەروەها خوران، ملوانکە، یان خوویەک. یەک دەستلێدان مانای کەمە؛ دووبارەبوونەوە مانای زیاترە.'),
  (17, 'en', 'Voice rising in pitch', 'Tension tightens the vocal cords.', 'Excitement does the same thing as nerves.'),
  (17, 'ckb', 'بەرزبوونەوەی دەنگ', 'گرژی ژێیەکانی دەنگ توند دەکات.', 'هەڵچوونی خۆش هەمان کار دەکات کە دڵەڕاوکێ دەیکات.'),
  (18, 'en', 'Raised and held', 'Cold, fear, bracing, wanting to be smaller.', 'A quick lift and drop is a shrug: "I don''t know" or "I don''t care".'),
  (18, 'ckb', 'بەرزکراوە و ڕاگیراو', 'سەرما، ترس، خۆئامادەکردن، ویستی بچووکبوونەوە.', 'بەرزکردنەوە و داخستنێکی خێرا شان هەڵتەکاندنە: "نازانم" یان "گرنگ نییە".'),
  (19, 'en', 'Dropped and rolled forward', 'Sadness, shame, tiredness, defeat.', 'Also long hours at a laptop. Watch for a change from how they usually sit.'),
  (19, 'ckb', 'داکەوتوو و بۆ پێشەوە خڕبووەوە', 'خەم، شەرم، ماندوێتی، شکست.', 'هەروەها کاتژمێرەها دانیشتن لەبەردەم لاپتۆپ. سەیری گۆڕانکاری بکە لە چۆنیەتی دانیشتنی ئاسایی کەسەکە.'),
  (20, 'en', 'Pulled back, chest open', 'Pride, readiness, confidence.', 'Exaggerated and held, it can be a show for others.'),
  (20, 'ckb', 'بۆ دواوە کشاو، سنگ کراوە', 'شانازی، ئامادەیی، متمانە.', 'ئەگەر زیادەڕۆیی تێدا بکرێت و ڕابگیرێت، دەکرێت نمایشێک بێت بۆ خەڵکی تر.'),
  (21, 'en', 'Open, expanded chest', 'Pride, triumph, confidence.', '"Power poses" do not reliably change hormones; the display is real, the life hack is not.'),
  (21, 'ckb', 'سنگی کراوە و فراوان', 'شانازی، سەرکەوتن، متمانە.', '"وەستانی هێز" بە شێوەیەکی جێی متمانە هۆرمۆنەکان ناگۆڕێت؛ نمایشەکە ڕاستە، فێڵە ژیانییەکە نا.'),
  (22, 'en', 'Arms or objects held across it', 'Protection, comfort, cold, or just a resting place for the arms.', 'A bag or folder held in front during a talk is often nerves.'),
  (22, 'ckb', 'باسک یان شتێک بەسەریدا گیراو', 'پاراستن، ئارامی، سەرما، یان تەنها شوێنێک بۆ پشوودانی باسکەکان.', 'جانتایەک یان فایلێک کە لە کاتی وتاردا لەبەردەم سنگ دەگیرێت، زۆرجار دڵەڕاوکێیە.'),
  (23, 'en', 'Fast, high breathing', 'Arousal: fear, anger, excitement, effort.', 'Slow breathing from the belly is the clearest sign of calm.'),
  (23, 'ckb', 'هەناسەی خێرا و بەرز', 'وروژان: ترس، تووڕەیی، هەڵچوون، هەوڵ.', 'هەناسەدانی هێواش لە سکەوە ڕوونترین نیشانەی ئارامییە.'),
  (24, 'en', 'Crossed arms', 'Cold, concentrating, comfortable, self-soothing, or closing off.', 'In one study, people with crossed arms kept working on hard puzzles longer. Context decides.'),
  (24, 'ckb', 'باسکی لێکئاڵاو', 'سەرما، سەرنجدان، ئاسوودەیی، ئارامکردنەوەی خۆ، یان خۆداخستن.', 'لە توێژینەوەیەکدا، ئەوانەی باسکیان لێک ئاڵاندبوو ماوەیەکی درێژتر لەسەر مەتەڵە سەختەکان کاریان کرد. بارودۆخ بڕیار دەدات.'),
  (25, 'en', 'Thrown up in a V', 'Triumph. Athletes born blind do it too, so it is not learned by watching.', 'Arms up with palms out is surrender instead.'),
  (25, 'ckb', 'بەرزکردنەوەیان بە شێوەی V', 'سەرکەوتن. وەرزشوانانی نابینای زگماکیش دەیکەن، کەواتە بە سەیرکردن فێر نابێت.', 'باسکی بەرزکراو لەگەڵ ناولەپی ڕووەو دەرەوە، خۆبەدەستەوەدانە.'),
  (26, 'en', 'Wrapped around yourself', 'Self-comfort: a hug you give yourself.', 'In a cold room it is just keeping warm.'),
  (26, 'ckb', 'باسک لە دەوری خۆ ئاڵاندن', 'دڵدانەوەی خۆ: باوەشێک کە بە خۆتی دەدەیت.', 'لە ژوورێکی سارددا تەنها خۆگەرمکردنەوەیە.'),
  (27, 'en', 'Touching the face, neck or hair', 'Self-soothing. It rises with any kind of stress.', 'Not a sign of lying: honest people under pressure touch their faces too.'),
  (27, 'ckb', 'دەستلێدانی دەموچاو، مل یان قژ', 'ئارامکردنەوەی خۆ. لەگەڵ هەر جۆرە فشارێکدا زیاد دەکات.', 'نیشانەی درۆ نییە: خەڵکی ڕاستگۆش لە ژێر فشاردا دەست لە دەموچاویان دەدەن.'),
  (28, 'en', 'Palms up', 'Openness, asking, "I don''t know".', 'With a shrug and raised brows, it is one of the most widely understood gestures.'),
  (28, 'ckb', 'ناولەپ بۆ سەرەوە', 'کراوەیی، داواکردن، "نازانم".', 'لەگەڵ شان هەڵتەکاندن و برۆی بەرز، یەکێکە لە تێگەیشتووترین جووڵەکان لە جیهاندا.'),
  (29, 'en', 'Hidden hands', 'Cold, habit, comfort, or nerves.', 'The claim that hidden hands mean "hiding something" has almost nothing behind it.'),
  (29, 'ckb', 'دەستی شاراوە', 'سەرما، خوو، ئاسوودەیی، یان دڵەڕاوکێ.', 'ئەو بانگەشەیەی دەستی شاراوە واتە "شتێک دەشارێتەوە" هیچ بەڵگەیەکی ئەوتۆی لە پشت نییە.'),
  (30, 'en', 'Fidgeting', 'Restlessness, nerves, boredom, or a lot of energy.', 'Some people always fidget. A change from their usual is what matters.'),
  (30, 'ckb', 'ئۆقرە نەگرتن', 'بێئارامی، دڵەڕاوکێ، بێزاری، یان وزەیەکی زۆر.', 'هەندێک کەس هەمیشە دەجووڵێن. ئەوەی گرنگە گۆڕانکارییە لە باری ئاسایییان.'),
  (31, 'en', 'Arms or a bag held over the belly', 'Protecting a soft place: discomfort, unease.', 'Also hunger, cramps, or carrying something.'),
  (31, 'ckb', 'باسک یان جانتا لەسەر سک گیراو', 'پاراستنی شوێنێکی نەرم: ناڕەحەتی، نائارامی.', 'هەروەها برسێتی، ژان، یان هەڵگرتنی شتێک.'),
  (32, 'en', 'A bouncing leg', 'Restlessness, nerves, energy, impatience, habit.', 'Baseline matters: some people bounce all day.'),
  (32, 'ckb', 'قاچ هەژاندن', 'بێئارامی، دڵەڕاوکێ، وزە، بێتاقەتی، خوو.', 'باری ئاسایی گرنگە: هەندێک کەس هەموو ڕۆژ قاچ دەهەژێنن.'),
  (33, 'en', 'A wide, planted stance', 'Stability, readiness, taking up space.', 'With fists and a forward lean, it is a threat display.'),
  (33, 'ckb', 'وەستانی فراوان و چەسپاو', 'جێگیری، ئامادەیی، داگیرکردنی شوێن.', 'لەگەڵ مشتی گیراو و خۆ بۆ پێشەوە نوشتاندنەوە، نمایشی هەڕەشەیە.'),
  (34, 'en', 'Legs crossed while standing', 'Comfort: you cannot run like that.', 'Also a full bladder.'),
  (34, 'ckb', 'قاچ لێکئاڵاندن لە کاتی وەستاندا', 'ئاسوودەیی: بەو شێوەیە ناتوانیت ڕابکەیت.', 'هەروەها میزڵدانێکی پڕ.'),
  (35, 'en', 'Feet turned toward the door', 'Possibly wanting to leave, while the face stays polite.', 'A hint, not proof. Feet also point where there is room to stand.'),
  (35, 'ckb', 'پێ ڕووەو دەرگا', 'لەوانەیە ویستی ڕۆیشتن بێت، لە کاتێکدا دەموچاو بە ڕێزەوە دەمێنێتەوە.', 'ئاماژەیە، نەک بەڵگە. پێیەکان ڕوو لەو شوێنەش دەکەن کە جێی وەستانی تێدایە.'),
  (36, 'en', 'Showing the soles of the shoes', 'Relaxed in some countries, insulting in much of the Middle East and Asia.', 'Same posture, opposite meaning: culture is context too.'),
  (36, 'ckb', 'نیشاندانی بنی پێڵاو', 'لە هەندێک وڵات ئاسوودەییە، لە زۆربەی ڕۆژهەڵاتی ناوەڕاست و ئاسیادا سووکایەتییە.', 'هەمان شێوەی دانیشتن، مانای پێچەوانە: کولتووریش بەشێکە لە بارودۆخ.');
