INSERT INTO feeling_texts (feeling_id, lang, name, note) VALUES
  (1, 'en', 'Anger', 'Upper body ready to act: head, chest, arms and fists.'),
  (1, 'ckb', 'تووڕەیی', 'نیوەی سەرەوەی جەستە ئامادەی کارکردنە: سەر، سنگ، باسکەکان و مشتەکان.'),
  (2, 'en', 'Fear', 'A pounding chest and a churning stomach.'),
  (2, 'ckb', 'ترس', 'سنگێک کە بە توندی لێدەدات و سکێک کە تێکدەچێت.'),
  (3, 'en', 'Disgust', 'The throat and gut: the body getting ready to reject something.'),
  (3, 'ckb', 'قێزلێبوونەوە', 'گەروو و ڕیخۆڵە: جەستە خۆی ئامادە دەکات بۆ ڕەتکردنەوەی شتێک.'),
  (4, 'en', 'Joy', 'The only feeling people report almost everywhere at once.'),
  (4, 'ckb', 'خۆشی', 'تاکە هەستێکە کە خەڵک دەڵێن نزیکەی لە هەموو شوێنێکی جەستەدا هەستی پێدەکەن.'),
  (5, 'en', 'Sadness', 'A heavy chest, and arms and legs that go quiet.'),
  (5, 'ckb', 'خەم', 'سنگێکی قورس، و باسک و قاچێک کە بێدەنگ دەبن.'),
  (6, 'en', 'Anxiety', 'A tight chest and an uneasy stomach.'),
  (6, 'ckb', 'دڵەڕاوکێ', 'سنگێکی تەنگ و سکێکی نائارام.'),
  (7, 'en', 'Love', 'Warmth across the head, chest and belly.'),
  (7, 'ckb', 'خۆشەویستی', 'گەرمی بە سەر و سنگ و سکدا.'),
  (8, 'en', 'Shame', 'A burning face, and limbs that want to disappear.'),
  (8, 'ckb', 'شەرم', 'دەموچاوێکی سووتاو، و ئەندامگەلێک کە دەیانەوێت ون ببن.'),
  (9, 'en', 'Pride', 'Head and chest: the body standing taller.'),
  (9, 'ckb', 'شانازی', 'سەر و سنگ: جەستە بەرزتر دەوەستێت.');
