INSERT INTO expression_texts (expression_id, lang, name, hint) VALUES
  (1, 'en', 'A genuine-looking smile', 'Let it reach your eyes: cheeks up, corners crinkled.'),
  (1, 'ckb', 'زەردەخەنەیەکی ڕاستەقینە', 'با بگاتە چاوەکانت: گۆنا بەرز، گۆشەکان چرچ.'),
  (2, 'en', 'A polite smile', 'Mouth only. Keep your eyes still.'),
  (2, 'ckb', 'زەردەخەنەیەکی بە ڕێز', 'تەنها دەم. چاوەکانت جێگیر بهێڵەوە.'),
  (3, 'en', 'Surprise', 'Brows high, eyes wide, jaw dropped.'),
  (3, 'ckb', 'سەرسوڕمان', 'برۆی بەرز، چاوی فراوان، شەویلگەی کراوە.'),
  (4, 'en', 'Worry', 'Lift only the inner ends of your brows. It is harder than it sounds.'),
  (4, 'ckb', 'نیگەرانی', 'تەنها سەرە ناوەکییەکانی برۆکانت بەرز بکەرەوە. لەوەی بیری لێدەکەیتەوە سەختترە.'),
  (5, 'en', 'Deep concentration', 'Brows down, eyes narrowed, lips pressed.'),
  (5, 'ckb', 'سەرنجی قووڵ', 'برۆ بۆ خوارەوە، چاو تەسک، لێو پەستێنراو.'),
  (6, 'en', 'Disgust', 'Wrinkle your nose as if something smells off.'),
  (6, 'ckb', 'قێزلێبوونەوە', 'لووتت چرچ بکە وەک ئەوەی بۆنێکی ناخۆش بێت.'),
  (7, 'en', 'Fear', 'Brows up and together, eyes wide, lips stretched back.'),
  (7, 'ckb', 'ترس', 'برۆی بەرز و پێکەوە، چاوی فراوان، لێو بۆ دواوە کێشراو.'),
  (8, 'en', 'Sadness', 'Inner brows up, mouth corners down.'),
  (8, 'ckb', 'خەم', 'برۆی ناوەوە بەرز، گۆشەی دەم بۆ خوارەوە.');
