INSERT INTO poker_prompt_texts (prompt_id, lang, text) VALUES
  (1, 'en', 'Imagine biting slowly into a raw lemon.'),
  (1, 'ckb', 'وا دابنێ بە هێواشی گاز لە لیمۆیەکی ترش دەگریت.'),
  (2, 'en', 'Remember the most embarrassing thing you said this year.'),
  (2, 'ckb', 'شەرمەزارترین قسەیەک بیر بکەرەوە کە ئەمساڵ کردووتە.'),
  (3, 'en', 'Picture your teacher dancing on the desk.'),
  (3, 'ckb', 'مامۆستاکەت بهێنە بەرچاو کە لەسەر مێزەکە سەما دەکات.'),
  (4, 'en', 'Someone behind you just shouted your name.'),
  (4, 'ckb', 'کەسێک لە پشتتەوە هاواری ناوت کرد.'),
  (5, 'en', 'You find a forgotten banknote in an old jacket.'),
  (5, 'ckb', 'پارەیەکی لەبیرکراو لە گیرفانی چاکەتێکی کۆندا دەدۆزیتەوە.'),
  (6, 'en', 'Smell the inside of a gym bag left closed for a week.'),
  (6, 'ckb', 'بۆنی ناو جانتایەکی وەرزش بکە کە هەفتەیەک داخراو بووە.'),
  (7, 'en', 'Your crush just liked your old photo from five years ago.'),
  (7, 'ckb', 'ئەو کەسەی دڵت پێیەتی وێنەیەکی کۆنی پێنج ساڵ لەمەوبەری تۆی لایک کرد.'),
  (8, 'en', 'Your phone screen cracks as it slips from your hand.'),
  (8, 'ckb', 'شاشەی مۆبایلەکەت دەشکێت کاتێک لە دەستت دەخلیسکێت.');
