INSERT INTO scenario_texts (scenario_id, lang, name, prompt) VALUES
  (1, 'en', 'Job interview', 'Tell me about yourself, and why you want this job.'),
  (1, 'ckb', 'چاوپێکەوتنی کار', 'باسی خۆتم بۆ بکە، و بۆچی ئەم کارەت دەوێت.'),
  (2, 'en', 'Class presentation', 'Explain something you learned recently that surprised you, as if to a full class.'),
  (2, 'ckb', 'پێشکەشکردن لە پۆلدا', 'شتێک ڕوون بکەرەوە کە بەم دواییانە فێری بوویت و سەری سوڕماندیت، وەک ئەوەی بۆ پۆلێکی پڕ بیڵێیت.'),
  (3, 'en', 'Meeting new people', 'Introduce yourself to a group you have never met.'),
  (3, 'ckb', 'ناسینی خەڵکی نوێ', 'خۆت بە گرووپێک بناسێنە کە هەرگیز نەتبینیون.'),
  (4, 'en', 'Saying no', 'A friend asks to copy your homework. Say no, kindly but clearly.'),
  (4, 'ckb', 'وتنی نا', 'هاوڕێیەک داوا دەکات ئەرکەکەت بگوازێتەوە. بە نەرمی بەڵام بە ڕوونی بڵێ نا.'),
  (5, 'en', 'Defending an opinion', 'Argue that your city is the best place to grow up.'),
  (5, 'ckb', 'بەرگریکردن لە بیروڕایەک', 'بەڵگە بهێنەرەوە کە شارەکەت باشترین شوێنە بۆ گەورەبوون.');
