  ('blinks', 'mixed', 1),
  ('smiles', 'mixed', 2),
  ('presses', 'mixed', 3),
  ('brows', 'mixed', 4),
  ('still', 'weak', 5),
  ('tilt', 'mixed', 6);
INSERT INTO report_measure_texts (measure, lang, title, reading) VALUES
  ('blinks', 'en', 'Blinks', 'In conversation people blink about 26 times a minute. Far more can come with stress or effort, far fewer with intense focus. A weak cue on its own.'),
  ('blinks', 'ckb', 'چاوترووکاندن', 'لە کاتی گفتوگۆدا خەڵک نزیکەی ٢٦ جار لە خولەکێکدا چاو دەترووکێنن. زۆر زیاتر دەکرێت لەگەڵ فشار یان هەوڵدا بێت، زۆر کەمتریش لەگەڵ سەرنجی توند. بە تەنها ئاماژەیەکی لاوازە.'),
  ('smiles', 'en', 'Smiles', 'Smiles that reach the eyes tend to read as warm; mouth-only smiles as polite. Both are normal. Many quick polite smiles under pressure can read as nervous.'),
  ('smiles', 'ckb', 'زەردەخەنە', 'ئەو زەردەخەنانەی دەگەنە چاوەکان زۆرجار وەک گەرم دەخوێنرێنەوە؛ ئەوانەی تەنها دەمن وەک ڕێزگرتن. هەردووکیان ئاساین. زۆر زەردەخەنەی خێرای ڕێزگرتن لە ژێر فشاردا دەکرێت وەک دڵەڕاوکێ بخوێنرێتەوە.'),
  ('presses', 'en', 'Lips pressed together', 'Pressed lips often read as holding something back: words, effort, tension. Notice whether they come just before the hard parts.'),
  ('presses', 'ckb', 'پەستانی لێوەکان', 'لێوی پەستێنراو زۆرجار وەک ڕاگرتنی شتێک دەخوێنرێتەوە: قسە، هەوڵ، گرژی. سەرنج بدە ئایا ڕاست پێش بەشە سەختەکان دێن.'),
  ('brows', 'en', 'Brows', 'Raised brows add emphasis and look engaged; lowered brows read as concentration, or as doubt. Brows that never move can read as flat.'),
  ('brows', 'ckb', 'برۆکان', 'برۆی بەرزکراوە جەخت زیاد دەکات و وەک بەشداریکردن دەردەکەوێت؛ برۆی داگیراو وەک سەرنجدان، یان گومان دەخوێنرێتەوە. برۆیەک کە هەرگیز ناجووڵێت دەکرێت وەک بێهەست بخوێنرێتەوە.'),
  ('still', 'en', 'A still face', 'A face that rarely moves reads as calm and in control, or as hard to read. Most people move something every few seconds while they talk.'),
  ('still', 'ckb', 'دەموچاوی بێجووڵە', 'دەموچاوێک کە کەم دەجووڵێت وەک ئارام و خۆگر دەخوێنرێتەوە، یان وەک سەخت بۆ خوێندنەوە. زۆربەی خەڵک لە کاتی قسەکردندا هەر چەند چرکەیەک شتێک دەجووڵێنن.'),
  ('tilt', 'en', 'Head tilted', 'A tilted head tends to read as listening and friendly; a level head as neutral or serious.'),
  ('tilt', 'ckb', 'سەری لارکراوە', 'سەری لار زۆرجار وەک گوێگرتن و دۆستانە دەخوێنرێتەوە؛ سەری ڕاست وەک بێلایەن یان جددی.');
INSERT INTO tests (id, slug, kind, position) VALUES
