  (2, 'body', 'body', 2),
  (3, 'context', 'context', 3);
INSERT INTO test_texts (test_id, lang, name, kicker, blurb) VALUES
  (1, 'en', 'The eyes test', 'Twelve faces, eyes only', 'Read a feeling from a thin strip of face, then watch the frame widen to the whole scene. The four choices are deliberately close, like the eyes test psychologists use.'),
  (1, 'ckb', 'تاقیکردنەوەی چاوەکان', 'دوازدە دەموچاو، تەنها چاوەکان', 'هەستێک لە پارچەیەکی باریکی دەموچاو بخوێنەوە، پاشان سەیر بکە چۆن چوارچێوەکە فراوان دەبێت بۆ هەموو دیمەنەکە. چوار هەڵبژاردنەکە بە ئەنقەست لە یەکەوە نزیکن، وەک ئەو تاقیکردنەوەی چاوەی دەروونناسان بەکاری دەهێنن.'),
  (2, 'en', 'The body test', 'Faces hidden until you answer', 'Posture, arms, head and stance. Read the body first; the face appears only after you answer. Sometimes the honest answer is that there is not enough to tell.'),
  (2, 'ckb', 'تاقیکردنەوەی جەستە', 'دەموچاو شاراوەیە تا وەڵام دەدەیتەوە', 'شێوەی وەستان، باسک، سەر و پێ. سەرەتا جەستەکە بخوێنەوە؛ دەموچاو تەنها دوای وەڵامدانەوەکەت دەردەکەوێت. هەندێک جار وەڵامی ڕاستگۆیانە ئەوەیە کە زانیاری بەس نییە.'),
  (3, 'en', 'The context test', 'Same body, different room', 'The same pose, placed in different scenes. Watch your answer change while the body stays exactly the same.'),
  (3, 'ckb', 'تاقیکردنەوەی بارودۆخ', 'هەمان جەستە، ژووری جیاواز', 'هەمان شێوەی جەستە، لە دیمەنی جیاوازدا. سەیر بکە چۆن وەڵامەکەت دەگۆڕێت لە کاتێکدا جەستەکە ڕێک وەک خۆی دەمێنێتەوە.');
