INSERT INTO question_texts (question_id, lang, prompt, title, cue, why, place, credit) VALUES
  (1, 'en', 'What are these eyes showing?', 'Suspicion', 'The lower lids tighten and push up, narrowing the eyes from below, while the gaze stays fixed on its target. The brows dip slightly but do not knot together.', 'Curiosity opens the eyes instead of narrowing them. Irritation pulls the brows down and together much harder. Tiredness lowers the upper lids, not the lower ones, and the gaze drifts instead of holding.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (1, 'ckb', 'ئەم چاوانە چی پیشان دەدەن؟', 'گومان', 'پێڵووی خوارەوە گرژ دەبێت و بەرەو سەرەوە پاڵ دەنێت، چاو لە خوارەوە تەسک دەکاتەوە، لە کاتێکدا نیگا لەسەر ئامانجەکەی جێگیر دەمێنێتەوە. برۆکان کەمێک دادەبەزن بەڵام گرێ نادرێن.', 'کونجکاوی چاو دەکاتەوە نەک تەسکی بکاتەوە. عاجزی برۆکان زۆر توندتر بۆ خوارەوە و پێکەوە ڕادەکێشێت. ماندوێتی پێڵووی سەرەوە دادەگرێت، نەک خوارەوە، و نیگا وێڵ دەبێت نەک جێگیر بمێنێت.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (2, 'en', 'What are these eyes showing?', 'Contempt', 'The head tips back so the eyes look down the nose, the upper lids sit half lowered, and the gaze is steady and unimpressed. In the full face, one corner of the mouth usually tightens: contempt is the one common expression that is often one-sided.', 'Amusement crinkles the outer corners of the eyes. Pride also tips the head back, but the eyes stay open and bright. Boredom lowers the lids too, but the gaze wanders instead of pinning its target.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (2, 'ckb', 'ئەم چاوانە چی پیشان دەدەن؟', 'بەکەمزانین', 'سەر بۆ دواوە لار دەبێتەوە تا چاوەکان بە سەر لووتدا سەیری خوارەوە بکەن، پێڵووی سەرەوە بە نیوەداخراوی دەمێنێتەوە، و نیگا جێگیر و بێباکە. لە هەموو دەموچاوەکەدا زۆرجار گۆشەیەکی دەم گرژ دەبێت: بەکەمزانین تاکە دەربڕینی باوە کە زۆرجار تەنها یەک لایە.', 'گاڵتەپێهاتن گۆشەی دەرەوەی چاوەکان چرچ دەکات. شانازیش سەر بۆ دواوە دەبات، بەڵام چاوەکان کراوە و گەش دەمێننەوە. بێزاریش پێڵووەکان دادەگرێت، بەڵام نیگا وێڵ دەبێت نەک لەسەر ئامانجەکەی بچەسپێت.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (3, 'en', 'What are these eyes showing?', 'Fear', 'The upper lids lift high enough to show white above the iris, and the lower lids tense at the same time. The brows rise but also pull together, which creases the middle of the forehead.', 'Surprise lifts the brows in a clean arch without pulling them together, and its lower lids stay relaxed. Alertness opens the eyes a little and leaves the brows alone. Anger can show white above the iris too, but under brows pulled down, not up.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (3, 'ckb', 'ئەم چاوانە چی پیشان دەدەن؟', 'ترس', 'پێڵووی سەرەوە ئەوەندە بەرز دەبێتەوە کە سپێتی چاو لە سەرووی ڕەشێنەکەوە دەردەکەوێت، و لە هەمان کاتدا پێڵووی خوارەوە گرژ دەبێت. برۆکان بەرز دەبنەوە بەڵام پێکەوەش ڕادەکێشرێن، و ناوەڕاستی ناوچەوان چرچ دەکەن.', 'سەرسوڕمان برۆکان بە کەوانێکی ڕێک بەرز دەکاتەوە بێ ئەوەی پێکەوەیان ڕابکێشێت، و پێڵووی خوارەوەی ئاسوودە دەمێنێتەوە. وریایی چاوەکان کەمێک دەکاتەوە و برۆکان بە خۆیان دەهێڵێت. تووڕەییش دەتوانێت سپێتی سەرووی ڕەشێنە پیشان بدات، بەڵام لە ژێر برۆی دابەزیودا، نەک بەرزبووەوە.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (4, 'en', 'What are these eyes showing?', 'Grief', 'Only the inner ends of the brows lift, slanting them up toward the middle, and the upper lids droop. The gaze is low or unfocused. Darwin called the muscles that make this slant the grief muscles.', 'Exhaustion droops the lids but leaves the brows flat. Thoughtfulness lowers the gaze without the slanted brows. Guilt looks down and away, but the brows do not lift in the middle.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (4, 'ckb', 'ئەم چاوانە چی پیشان دەدەن؟', 'خەفەت', 'تەنها سەرە ناوەکییەکانی برۆکان بەرز دەبنەوە و بەرەو ناوەڕاست لاریان دەکەنەوە، و پێڵووی سەرەوە شۆڕ دەبێتەوە. نیگا نزمە یان لەسەر هیچ نییە. داروین ئەو ماسولکانەی ئەم لاربوونەوەیە دروست دەکەن ناونا "ماسولکەکانی خەفەت".', 'شەکەتی پێڵووەکان شۆڕ دەکاتەوە بەڵام برۆکان ڕاست دەهێڵێت. بیرکردنەوە نیگا نزم دەکاتەوە بێ برۆی لار. هەستی تاوان سەیری خوارەوە و لایەک دەکات، بەڵام برۆکان لە ناوەڕاستەوە بەرز نابنەوە.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (5, 'en', 'What are these eyes showing?', 'Amusement', 'The cheeks lift and push the lower lids up from below, and fine lines fan out from the outer corners: the crinkle of a smile that is actually felt. The brows stay relaxed.', 'A flirtatious look holds the gaze longer, often with the head tipped down. Smugness half-lowers the upper lids with little crinkle. A friendly face can smile politely without lifting the cheeks at all.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (5, 'ckb', 'ئەم چاوانە چی پیشان دەدەن؟', 'گاڵتەپێهاتن', 'گۆنا بەرز دەبنەوە و پێڵووی خوارەوە لە خوارەوە بۆ سەرەوە پاڵ دەنێن، و هێڵی باریک لە گۆشەی دەرەوەی چاوەکانەوە بڵاو دەبنەوە: چرچی زەردەخەنەیەک کە بەڕاستی هەستی پێدەکرێت. برۆکان ئاسوودە دەمێننەوە.', 'نیگای عیشوەگەرانە زیاتر دەمێنێتەوە، زۆرجار لەگەڵ سەرێکی کەمێک شۆڕکراوەدا. لەخۆبایی بوون پێڵووی سەرەوە بە نیوەیی دادەگرێت بە چرچێکی کەمەوە. دەموچاوێکی ڕووخۆش دەتوانێت بە ڕێزەوە زەردەخەنە بکات بێ ئەوەی گۆنا بەرز بکاتەوە.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (6, 'en', 'What are these eyes showing?', 'Distress', 'The eyes are open wide but not fixed on anything, and the inner brows are raised and drawn together, putting tension across the middle of the forehead. Distress looks like fear and sadness at once.', 'Confusion pulls the brows down and narrows the eyes to focus. Exhaustion lets the lids sag. Sadness shares the raised inner brows, but its eyes are heavy, not wide.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (6, 'ckb', 'ئەم چاوانە چی پیشان دەدەن؟', 'پەشێوی', 'چاوەکان بە فراوانی کراونەتەوە بەڵام لەسەر هیچ شتێک جێگیر نین، و سەرە ناوەکییەکانی برۆکان بەرز و لێک نزیک دەبنەوە و گرژییەک دەخەنە ناوەڕاستی ناوچەوانەوە. پەشێوی وەک ترس و خەم پێکەوە دەردەکەوێت.', 'سەرلێشێوان برۆکان دادەگرێت و چاوەکان تەسک دەکاتەوە بۆ سەرنجدان. شەکەتی پێڵووەکان شۆڕ دەکات. خەم هەمان برۆی بەرزی ناوەکیی هەیە، بەڵام چاوەکانی قورسن نەک فراوان.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (7, 'en', 'What are these eyes showing?', 'Fury', 'The brows drive down and together while the upper lids stay raised, so the eyes glare out from under a heavy frown, and the lower lids tighten. A lowered brow over wide eyes is the stare of anger.', 'Determination lowers the brows but keeps the lids calm. Disgust wrinkles the nose and narrows the eyes from below. Suspicion narrows the eyes without the hard glare.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (7, 'ckb', 'ئەم چاوانە چی پیشان دەدەن؟', 'ڕقهەستان', 'برۆکان بە توندی بۆ خوارەوە و پێکەوە دەچن لە کاتێکدا پێڵووی سەرەوە بەرز دەمێنێتەوە، بۆیە چاوەکان لە ژێر ڕووگرژییەکی قورسەوە زەق دەڕوانن، و پێڵووی خوارەوە گرژ دەبێت. برۆی دابەزیو لەسەر چاوی فراوان، نیگای تووڕەییە.', 'سووربوون برۆکان دادەگرێت بەڵام پێڵووەکان ئارام دەهێڵێت. قێزلێبوونەوە لووت چرچ دەکات و چاوەکان لە خوارەوە تەسک دەکاتەوە. گومان چاوەکان تەسک دەکاتەوە بێ ئەو زەقڕوانینە توندە.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (8, 'en', 'What are these eyes showing?', 'Shame', 'The gaze drops down and away from everyone and the upper lids lower with it; the head usually bows too. Shame wants to hide, so the eyes avoid contact on purpose.', 'Sadness looks down too, but its inner brows rise. Thoughtfulness lets the gaze drift without hiding it. Shyness glances away and then back again, checking.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (8, 'ckb', 'ئەم چاوانە چی پیشان دەدەن؟', 'شەرم', 'نیگا بۆ خوارەوە و دوور لە هەمووان دادەبەزێت و پێڵووی سەرەوەش لەگەڵیدا دادەبەزێت؛ سەریش زۆرجار شۆڕ دەبێتەوە. شەرم دەیەوێت خۆی بشارێتەوە، بۆیە چاوەکان بە ئەنقەست خۆیان لە بەریەککەوتن لادەدەن.', 'خەمیش سەیری خوارەوە دەکات، بەڵام برۆ ناوەکییەکانی بەرز دەبنەوە. بیرکردنەوە نیگا وێڵ دەکات بێ ئەوەی بیشارێتەوە. شەرمنی سەیری لایەک دەکات و دواتر دەگەڕێتەوە بۆ ئەوەی ببینێت.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (9, 'en', 'What are these eyes showing?', 'Worry', 'The inner brows lift and pull slightly together, making small vertical creases between them, while the eyes stay steady and focused on the problem.', 'Fear has the same brows but opens the eyes wide. Thoughtfulness keeps the brows flat. Sadness lifts the inner brows too, but the lids are heavy and the gaze drops.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (9, 'ckb', 'ئەم چاوانە چی پیشان دەدەن؟', 'نیگەرانی', 'برۆ ناوەکییەکان بەرز دەبنەوە و کەمێک پێکەوە ڕادەکێشرێن، چرچی ستوونیی بچووک لە نێوانیاندا دروست دەکەن، لە کاتێکدا چاوەکان جێگیرن و سەرنجیان لەسەر کێشەکەیە.', 'ترس هەمان برۆی هەیە بەڵام چاوەکان بە فراوانی دەکاتەوە. بیرکردنەوە برۆکان ڕاست دەهێڵێت. خەمیش برۆ ناوەکییەکان بەرز دەکاتەوە، بەڵام پێڵووەکان قورسن و نیگا دادەبەزێت.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (10, 'en', 'What are these eyes showing?', 'Curiosity', 'The eyes open a little wider and lock onto one thing, the brows lift slightly, and the head often tilts. Everything points toward what is being looked at.', 'Surprise is bigger and brief: brows high, eyes very wide. Suspicion narrows the eyes instead of opening them. Flirtation adds softness under the eyes and a glance that comes and goes.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (10, 'ckb', 'ئەم چاوانە چی پیشان دەدەن؟', 'کونجکاوی', 'چاوەکان کەمێک زیاتر دەکرێنەوە و لەسەر یەک شت دەچەسپێن، برۆکان کەمێک بەرز دەبنەوە، و سەر زۆرجار لار دەبێتەوە. هەموو شتێک ڕووەو ئەو شتەیە کە سەیر دەکرێت.', 'سەرسوڕمان گەورەتر و کورتترە: برۆی زۆر بەرز، چاوی زۆر فراوان. گومان چاوەکان تەسک دەکاتەوە نەک بیانکاتەوە. عیشوەگەری نەرمییەک دەخاتە ژێر چاوەکان و نیگایەک کە دێت و دەڕوات.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (11, 'en', 'What are these eyes showing?', 'Smugness', 'The upper lids sit half lowered and relaxed, the head tilts back a little, and the eyes hold yours longer than they need to. A look of quiet winning.', 'Amusement crinkles the corners of the eyes. Contentment is relaxed too, but it does not hold your gaze. Confidence holds the gaze with the lids fully open, not lowered.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (11, 'ckb', 'ئەم چاوانە چی پیشان دەدەن؟', 'لەخۆبایی بوون', 'پێڵووی سەرەوە بە نیوەیی و ئاسوودەیی داخراوە، سەر کەمێک بۆ دواوە لار دەبێتەوە، و چاوەکان لەوەی پێویستە زیاتر سەیرت دەکەن. نیگای بردنەوەیەکی بێدەنگە.', 'گاڵتەپێهاتن گۆشەی چاوەکان چرچ دەکات. ڕازیبوونیش ئاسوودەیە، بەڵام نیگات ڕاناگرێت. متمانە نیگا ڕادەگرێت بە پێڵووی تەواو کراوە، نەک داخراو.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (12, 'en', 'What are these eyes showing?', 'Affection', 'The lids soften and lower slightly, a faint smile lifts the lower lids a touch, and the gaze rests on its object instead of scanning. The brows are completely relaxed.', 'Sadness softens the eyes too, but lifts the inner brows. Gratitude is often wider-eyed and brief. Tiredness lowers the lids without any lift from the cheeks.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (12, 'ckb', 'ئەم چاوانە چی پیشان دەدەن؟', 'سۆز', 'پێڵووەکان نەرم دەبن و کەمێک دادەبەزن، زەردەخەنەیەکی کاڵ پێڵووی خوارەوە کەمێک بەرز دەکاتەوە، و نیگا لەسەر ئەو کەسە دەحەسێتەوە نەک بگەڕێت. برۆکان بە تەواوی ئاسوودەن.', 'خەمیش چاوەکان نەرم دەکات، بەڵام برۆ ناوەکییەکان بەرز دەکاتەوە. سوپاسگوزاری زۆرجار چاوی کراوەترە و کورتە. ماندوێتی پێڵووەکان دادەگرێت بێ هیچ بەرزبوونەوەیەک لە گۆناکانەوە.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (13, 'en', 'What is this body saying?', 'Confidence', 'Upright without stiffness: shoulders back and down, chin level, weight spread evenly, hands still. Nothing is guarding the body and nothing is fidgeting.', 'Arrogance tips the chin up and takes more space than it needs. Relaxed bodies lean or slump. Defensive ones cross, turn away or put something in front of the chest.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (13, 'ckb', 'ئەم جەستەیە چی دەڵێت؟', 'متمانە', 'ڕاست بەبێ ڕەقی: شانەکان بۆ دواوە و خوارەوە، چەناگە ڕاست، قورسایی بە یەکسانی دابەشکراو، دەستەکان ئارام. هیچ شتێک جەستە ناپارێزێت و هیچ شتێک ناجووڵێت.', 'لووتبەرزی چەناگە بەرز دەکاتەوە و لەوەی پێویستە شوێنی زیاتر دەگرێت. جەستەی ئاسوودە پاڵ دەداتەوە یان دادەکەوێت. جەستەی خۆپارێز باسک لێک دەئاڵێنێت، ڕوو وەردەگێڕێت یان شتێک دەخاتە بەردەم سنگ.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (14, 'en', 'What is this body saying?', 'Defensive', 'Arms folded high and tight across the chest, torso angled away, chin dropped a little: several closed signals at once, and aimed at someone.', 'Cold folds the arms too, but hunches the shoulders and tucks the hands in. Boredom slumps or leans instead of bracing. Thinking usually crosses one arm and touches the face with the other hand.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (14, 'ckb', 'ئەم جەستەیە چی دەڵێت؟', 'خۆپاراستن', 'باسکەکان بە بەرزی و توندی بەسەر سنگدا لێک ئاڵاون، لاشە کەمێک ڕووی وەرگێڕاوە، و چەناگە کەمێک دابەزیوە: چەند ئاماژەیەکی داخراو پێکەوە، و ڕووەو کەسێک.', 'سەرماش باسکەکان لێک دەئاڵێنێت، بەڵام شانەکان کۆدەکاتەوە و دەستەکان دەشارێتەوە. بێزاری دادەکەوێت یان پاڵ دەداتەوە نەک خۆی ئامادە بکات. بیرکردنەوە زۆرجار یەک باسک لێک دەدات و بە دەستەکەی تر دەست لە دەموچاو دەدات.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (15, 'en', 'What is this body saying?', 'Defeat', 'The upper body collapses forward: shoulders rolled in, head hanging, arms limp. The body has stopped holding itself up. Athletes who lose show the same shape, even ones born blind.', 'Tiredness slumps too, but usually leans back or rests the head on something. Thinking bends forward with the head propped on a hand. A relaxed body loosens without folding inward.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (15, 'ckb', 'ئەم جەستەیە چی دەڵێت؟', 'شکست', 'نیوەی سەرەوەی جەستە بۆ پێشەوە دادەڕمێت: شانەکان بۆ ناوەوە خڕ بوونەتەوە، سەر شۆڕبووەتەوە، باسکەکان شل. جەستە وازی لە ڕاگرتنی خۆی هێناوە. وەرزشوانانی دۆڕاو هەمان شێوە پیشان دەدەن، تەنانەت ئەوانەی بە نابینایی لەدایک بوون.', 'ماندوێتیش دادەکەوێت، بەڵام زۆرجار پاڵ دەداتەوە یان سەر لەسەر شتێک دادەنێت. بیرکردنەوە بۆ پێشەوە دەچەمێتەوە بە سەرێکی لەسەر دەست. جەستەی ئاسوودە شل دەبێتەوە بێ ئەوەی بۆ ناوەوە بچەمێتەوە.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (16, 'en', 'What is this body saying?', 'Anxiety', 'A hand reaches for the neck, face, hair or the other arm: self-touch that soothes. The shoulders rise toward the ears and the body pulls in.', 'Thoughtful self-touch is slower and stays on the chin. Cold bodies rub their arms, without the raised, braced shoulders. Boredom leans its face lazily on a hand.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (16, 'ckb', 'ئەم جەستەیە چی دەڵێت؟', 'دڵەڕاوکێ', 'دەستێک دەچێتە سەر مل، دەموچاو، قژ یان باسکەکەی تر: دەستلێدانێک کە ئارام دەکاتەوە. شانەکان بەرەو گوێکان بەرز دەبنەوە و جەستە خۆی کۆدەکاتەوە.', 'دەستلێدانی بیرکردنەوە هێواشترە و لەسەر چەناگە دەمێنێتەوە. جەستەی سارد باسکەکانی دەسوێت، بەبێ شانی بەرزبووەوە و ئامادەباش. بێزاری بە تەمبەڵی دەموچاو لەسەر دەست دادەنێت.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (17, 'en', 'What is this body saying?', 'Dominance', 'It takes up space and claims height: a wide stance, hands on hips or planted on a table, standing over someone who is sitting. The posture is aimed at another person.', 'Anger leans in with tension in the hands and jaw. Confidence is upright but does not need to loom. Impatience shifts its weight and looks at the time or the door.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (17, 'ckb', 'ئەم جەستەیە چی دەڵێت؟', 'زاڵبوون', 'شوێن دەگرێت و بەرزی بۆ خۆی دەبات: وەستانی فراوان، دەست لەسەر کەمەر یان لەسەر مێز، بە سەر کەسێکی دانیشتوودا وەستاوە. شێوەی وەستانەکە ڕووەو کەسێکی ترە.', 'تووڕەیی بە گرژی لە دەست و شەویلگەدا بۆ پێشەوە دەچێت. متمانە ڕاستە بەڵام پێویستی بەوە نییە بەسەر کەسدا بوەستێت. بێتاقەتی قورسایی دەگۆڕێت و سەیری کاتژمێر یان دەرگا دەکات.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (18, 'en', 'What is this body saying?', 'Threat', 'It closes the distance into someone else''s personal space, shoulders squared, head forward, body still. The stillness matters: it is aimed, not upset.', 'Anger moves more: gestures, a raised voice, tension being released. Intimacy also comes close, but the body softens and the other person leans in too. Curiosity tilts the head instead of squaring up.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (18, 'ckb', 'ئەم جەستەیە چی دەڵێت؟', 'هەڕەشە', 'دوورییەکە کەم دەکاتەوە و دەچێتە ناو بۆشایی تایبەتی کەسێکی ترەوە، شانەکان ڕێک، سەر بۆ پێشەوە، جەستە بێجووڵە. بێجووڵەییەکە گرنگە: ئاراستەکراوە، نەک تێکچوو.', 'تووڕەیی زیاتر دەجووڵێت: جووڵەی دەست، دەنگی بەرز، گرژییەک کە دەتەقێتەوە. نزیکایەتیش نزیک دەبێتەوە، بەڵام جەستە نەرم دەبێت و کەسەکەی تریش بەرەو پێشەوە دێت. کونجکاوی سەر لار دەکاتەوە نەک خۆی ڕێک بکات.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (19, 'en', 'What is this body saying?', 'Withdrawal', 'The body makes itself small and turns away from the others: arms around itself, shoulders drawn in, at the edge of the room. It is closing a door.', 'Cold bodies hug themselves too, but they keep moving: rubbing, bouncing, stamping. Shyness turns away and then glances back. Sadness slumps, but does not necessarily turn away from people.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (19, 'ckb', 'ئەم جەستەیە چی دەڵێت؟', 'خۆدوورخستنەوە', 'جەستە خۆی بچووک دەکاتەوە و ڕوو لە خەڵکی تر وەردەگێڕێت: باسک لە دەوری خۆی، شانی کۆکراوە، لە لێواری ژوورەکەدا. دەرگایەک دادەخات.', 'جەستەی سارد خۆی لە باوەش دەگرێت، بەڵام بەردەوام دەجووڵێت: دەسوێت، دەلەرزێت، پێ دەکوتێت. شەرمنی ڕوو وەردەگێڕێت و دواتر سەیر دەکاتەوە. خەم دادەکەوێت، بەڵام مەرج نییە ڕوو لە خەڵک وەربگێڕێت.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (20, 'en', 'What is this body saying?', 'Control', 'Very upright and very still: hands clasped behind the back or in front, feet together, no self-touching, no shifting weight. The stillness is held, not resting.', 'Calm bodies are still too, but loose: they lean, settle and breathe. Boredom slumps and fidgets. Respect stands up straight for a moment, then relaxes once the formal moment passes.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (20, 'ckb', 'ئەم جەستەیە چی دەڵێت؟', 'خۆگرتن', 'زۆر ڕاست و زۆر بێجووڵە: دەستەکان لە پشتەوە یان لە پێشەوە پێکەوە گیراون، پێیەکان پێکەوە، بێ دەستلێدانی خۆ، بێ گۆڕینی قورسایی. بێجووڵەییەکە ڕاگیراوە، نەک پشوو.', 'جەستەی ئارامیش بێجووڵەیە، بەڵام شلە: پاڵ دەداتەوە، جێگیر دەبێت و هەناسە دەدات. بێزاری دادەکەوێت و دەجووڵێت. ڕێزگرتن بۆ ساتێک ڕاست دەوەستێت، پاشان دوای تێپەڕبوونی ساتە فەرمییەکە ئاسوودە دەبێتەوە.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (21, 'en', 'What is this person feeling?', 'Not enough to tell', 'Head in hands comes with despair, exhaustion, relief, helpless laughter and plain headaches. With the face hidden and no scene, the body alone cannot tell them apart.', 'Each of the other answers would be right in some scene, which is the lesson: one posture, many meanings. Now that the face is visible, look at what the posture alone could not tell you.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (21, 'ckb', 'ئەم کەسە هەستی بە چی دەکات؟', 'زانیاری بەس نییە', 'سەر لە ناو دەستەکاندا لەگەڵ بێهیوایی، شەکەتی، حەسانەوە، پێکەنینی بێدەسەڵات و تەنها سەرئێشەش دێت. بە دەموچاوێکی شاراوە و بێ دیمەن، جەستە بە تەنها ناتوانێت لێکیان جیا بکاتەوە.', 'هەر یەکێک لە وەڵامەکانی تر لە دیمەنێکدا ڕاست دەبێت، و ئەمە وانەکەیە: یەک شێوە، چەندین مانا. ئێستا کە دەموچاو دیارە، سەیری ئەوە بکە کە شێوەی جەستە بە تەنها نەیدەتوانی پێت بڵێت.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (22, 'en', 'What does this gesture tell you?', 'Not enough to tell', 'Fingertips pressed together is sold in body-language books as a sign of confidence or power. There is very little research behind that. People steeple while listening, thinking, or just resting their hands.', 'Confident and calculating are what the popular books would say. Listening is just as likely. Without the face, the voice and the moment, the hands alone are a guess.', NULL, 'Film still, the property of its owners, used here for teaching.'),
  (22, 'ckb', 'ئەم جووڵەیە چیت پێدەڵێت؟', 'زانیاری بەس نییە', 'نانی سەرەپەنجەکان بە یەکەوە لە کتێبەکانی زمانی جەستەدا وەک نیشانەی متمانە یان دەسەڵات دەفرۆشرێت. توێژینەوەیەکی زۆر کەم لە پشتی ئەمەوەیە. خەڵک لە کاتی گوێگرتن، بیرکردنەوە یان تەنها پشوودانی دەستەکانیاندا ئەمە دەکەن.', 'متمانە و حیسابکردن ئەوەن کە کتێبە بەناوبانگەکان دەیڵێن. گوێگرتنیش بە هەمان ئەندازە ئەگەری هەیە. بەبێ دەموچاو، دەنگ و ساتەکە، دەستەکان بە تەنها تەنها مەزەندەن.', NULL, 'وێنەیەک لە فیلمێک، موڵکی خاوەنەکانیەتی، بۆ مەبەستی فێرکردن بەکارهاتووە.'),
  (23, 'en', 'Why are their arms crossed?', 'Keeping warm', 'Snow, a cold blue light, nobody else around. Folding the arms traps heat against the body.', 'The pose has not changed in the next two questions. Only the room will.', 'A bus stop in the snow', ''),
  (23, 'ckb', 'بۆچی باسکیان لێک ئاڵاندووە؟', 'خۆگەرمکردنەوە', 'بەفر، ڕووناکییەکی شینی سارد، هیچ کەسێکی تر لەوێ نییە. لێکئاڵاندنی باسکەکان گەرمی لە نزیک جەستە ڕادەگرێت.', 'شێوەی جەستە لە دوو پرسیارەکەی داهاتوودا ناگۆڕێت. تەنها ژوورەکە دەگۆڕێت.', 'وەستگەی پاسێک لە ناو بەفردا', ''),
  (24, 'en', 'Why are their arms crossed?', 'Closed off', 'Here the classic reading fits: crossed arms during a disagreement, squared up to the other person, reads as "I am not moving".', 'It is exactly the same silhouette as the cold bus stop. The other person and the red heat of the room changed the meaning.', 'Mid-argument, face to face', ''),
  (24, 'ckb', 'بۆچی باسکیان لێک ئاڵاندووە؟', 'خۆداخستن', 'لێرەدا خوێندنەوە کلاسیکییەکە دەگونجێت: باسکی لێکئاڵاو لە کاتی ناکۆکیدا، ڕووبەڕووی کەسەکەی تر، وەک "من لە جێی خۆم ناجووڵێم" دەخوێنرێتەوە.', 'ڕێک هەمان سێبەری وەستگەی پاسە ساردەکەیە. کەسەکەی تر و گەرمیی سووری ژوورەکە ماناکەیان گۆڕی.', 'لە ناوەڕاستی دەمەقاڵێدا، ڕووبەڕوو', ''),
  (25, 'en', 'Why are their arms crossed?', 'Concentrating', 'Facing a speaker in a quiet room, still and upright. Many people fold their arms to settle and listen.', 'In one study, people who crossed their arms kept working on hard puzzles longer than people who did not. Crossed arms can mean focus.', 'Third row of a lecture', ''),
  (25, 'ckb', 'بۆچی باسکیان لێک ئاڵاندووە؟', 'سەرنجدان', 'ڕووی لە قسەکەرێکە لە ژوورێکی بێدەنگدا، بێجووڵە و ڕاست. زۆر کەس باسکیان لێک دەئاڵێنن بۆ ئەوەی جێگیر بن و گوێ بگرن.', 'لە توێژینەوەیەکدا، ئەوانەی باسکیان لێک ئاڵاندبوو ماوەیەکی درێژتر لەسەر مەتەڵە سەختەکان مانەوە. باسکی لێکئاڵاو دەتوانێت مانای سەرنج بێت.', 'ڕیزی سێیەمی وانەیەک', ''),
  (26, 'en', 'What just happened?', 'A near miss', 'Hands on the head under floodlights, surrounded by a crowd: the universal "I can''t believe it" of a ball that hit the post.', 'Out of context, hands on the head look like grief. The scene makes it a passing groan, gone in seconds.', 'A stadium, last minute of the match', ''),
  (26, 'ckb', 'چی ڕوویدا؟', 'خەریک بوو!', 'دەست لەسەر سەر لە ژێر ڕووناکیی یاریگادا، لە ناو جەماوەرێکدا: "باوەڕ ناکەم"ـی جیهانیی تۆپێک کە بەر دارەکە کەوت.', 'لە دەرەوەی بارودۆخ، دەست لەسەر سەر وەک ماتەم دەردەکەوێت. دیمەنەکە دەیکاتە ئاخێکی تێپەڕ کە لە چەند چرکەیەکدا نامێنێت.', 'یاریگایەک، دوایین خولەکی یارییەکە', ''),
  (27, 'en', 'What is this person feeling?', 'Overwhelmed', 'The same hands-on-head posture, but alone, at a desk, under a single lamp. Here it reads as too much to handle.', 'The body is identical to the stadium. Being alone with work changes a groan into a weight.', 'Late at night, at a desk', ''),
  (27, 'ckb', 'ئەم کەسە هەستی بە چی دەکات؟', 'بارگرانی', 'هەمان شێوەی دەست لەسەر سەر، بەڵام بە تەنها، لەسەر مێزێک، لە ژێر یەک چرادا. لێرەدا وەک ئەوە دەخوێنرێتەوە کە کارەکە لە توانای بەدەرە.', 'جەستەکە هەمان جەستەی یاریگاکەیە. تەنهایی لەگەڵ کار ئاخێک دەکاتە قورساییەک.', 'درەنگانی شەو، لەسەر مێزێک', ''),
  (28, 'en', 'What does the raised fist mean here?', 'Solidarity', 'A fist held high and still, among other people doing the same thing: a long-standing sign of unity and protest.', 'A fist aimed at a person would be a threat. In a crowd pointing upward, it is collective.', 'A march, among others doing the same', ''),
  (28, 'ckb', 'مشتی بەرزکراوە لێرەدا مانای چییە؟', 'هاوپشتی', 'مشتێک کە بەرز و جێگیر ڕاگیراوە، لە ناو خەڵکێکدا کە هەمان شت دەکەن: نیشانەیەکی کۆنی یەکگرتوویی و ناڕەزایی.', 'مشتێک کە ڕووەو کەسێک بێت هەڕەشە دەبوو. لە ناو جەماوەرێکدا کە ڕووەو سەرەوەیە، بەکۆمەڵە.', 'خۆپیشاندانێک، لە ناو خەڵکێکدا کە هەمان شت دەکەن', ''),
  (29, 'en', 'What does the raised fist mean here?', 'Celebrating', 'The same fist, alone in a gold spotlight with confetti falling. Now it is triumph.', 'Same arm, same fist, same angle as the march. One scene made it collective, the other personal.', 'The moment after winning', ''),
  (29, 'ckb', 'مشتی بەرزکراوە لێرەدا مانای چییە؟', 'ئاهەنگگێڕان', 'هەمان مشت، بە تەنها لە ژێر ڕووناکییەکی زێڕیندا و کاغەزی ڕەنگاوڕەنگ دەبارێت. ئێستا سەرکەوتنە.', 'هەمان باسک، هەمان مشت، هەمان گۆشەی خۆپیشاندانەکە. دیمەنێک کردییە بەکۆمەڵ، ئەوی تر کردییە کەسی.', 'ساتی دوای بردنەوە', ''),
  (30, 'en', 'What does the hand on the heart mean here?', 'Respect', 'Across Kurdistan and the wider Middle East, a right hand on the heart with a slight bow greets elders with respect, and can replace a handshake.', 'The same gesture swears sincerity in an argument, or means "that touched me" between friends. Culture is part of context.', 'Greeting an older relative in Erbil', ''),
  (30, 'ckb', 'دەست لەسەر دڵ لێرەدا مانای چییە؟', 'ڕێزگرتن', 'لە سەرانسەری کوردستان و ڕۆژهەڵاتی ناوەڕاستدا، دەستی ڕاست لەسەر دڵ لەگەڵ کەمێک چەمانەوە سڵاوێکی بەڕێزە بۆ بەتەمەنان، و دەتوانێت جێی تەوقەکردن بگرێتەوە.', 'هەمان جووڵە لە دەمەقاڵێدا ڕاستگۆیی دووپات دەکاتەوە، یان لە نێوان هاوڕێیاندا مانای "کاری تێکردم" دەدات. کولتووریش بەشێکە لە بارودۆخ.', 'سڵاوکردن لە خزمێکی بەتەمەن لە هەولێر', '');
